import XCTest

final class ElementUITest: XCTestCase {

    override func setUp() {
        super.setUp()
        continueAfterFailure = false
    }

    func testTeamStandupThreads() throws {
        let app = XCUIApplication()
        app.launch()

        XCTAssertTrue(app.wait(for: .runningForeground, timeout: 5))

        // Handle the dialog if it appears
        let openButton = app.buttons["Open"]
        if openButton.waitForExistence(timeout: 2) {
            openButton.tap()
        }

        // Wait a moment for the dialog to process
        usleep(1_000_000)

        // Try to find Team Standup room by looking for staticTexts containing "Team Standup"
        let teamStandupElements = app.staticTexts.matching(NSPredicate(format: "label CONTAINS 'Team Standup'"))
        XCTAssertGreaterThan(teamStandupElements.count, 0, "Should find Team Standup room")

        if teamStandupElements.count > 0 {
            let firstRoom = teamStandupElements.element(boundBy: 0)
            if firstRoom.waitForExistence(timeout: 2) {
                firstRoom.tap()
            }
        }

        // Wait for the room to load
        usleep(2_000_000)

        // Try to find the threads button/icon
        // Look for buttons that contain "thread" or have thread-related accessibility labels
        let threadsButton = app.buttons.matching(NSPredicate(format: "label CONTAINS[cd] 'thread'")).firstMatch
        if threadsButton.exists {
            threadsButton.tap()
        } else {
            // Try alternative ways to find the threads button
            let allButtons = app.buttons.allElementsBoundByAccessibilityElement
            for button in allButtons {
                if button.label.lowercased().contains("thread") {
                    button.tap()
                    break
                }
            }
        }
    }
}
EOF

